and desugar_args (env : FStarC_Syntax_DsEnv.env) (eta : ((FStarC_Parser_AST.term * FStarC_Parser_AST.imp)) list) : (((FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax * (FStarC_Syntax_Syntax.arg_qualifier) option)) list =
