      (match tmp with
        | (bb, aqs') -> (let tmp1 = (as_binder env (hd).FStarC_Parser_AST.aqual bb) in
          (match tmp1 with
            | (b, env1) -> ((desugar_term_maybe_top__aux top setpos t) env1 (FStarC_List.op_At aqs' aqs) (b :: bs) tl)
          ))
