      let ses1 = (if tmp1 then (FStarC_List.map (fun se -> { FStarC_Syntax_Syntax.sigel = (se).FStarC_Syntax_Syntax.sigel;
          sigrng = (se).FStarC_Syntax_Syntax.sigrng;
