let desugar_modul_common (curmod : (FStarC_Syntax_Syntax.modul) option) (env : FStarC_Syntax_DsEnv.env) (m : FStarC_Parser_AST.modul) : (FStarC_Syntax_DsEnv.env * FStarC_Syntax_Syntax.modul * bool) =
