      | ((Some (prev_mod)), tmp) -> (let tmp1 = (FStarC_Syntax_DsEnv.finish_module_or_interface env prev_mod) in
        (Custard_FStar_Pervasives_Native.fStar_Pervasives_Native_fst tmp1))
