  )))))

let ast_modul_to_modul (modul : FStarC_Parser_AST.modul) : (FStarC_Syntax_DsEnv.env -> (FStarC_Syntax_Syntax.modul * FStarC_Syntax_DsEnv.env)) =
  (fun env -> (with_options (fun tmp -> (let tmp1 = (desugar_modul env modul) in
  (match tmp1 with
